contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Attempt withdrawal: provide caller address (msgSender) and recipient and amount to fund this test contract
    // The test must be called by some external address in the harness; we model that by using msg.sender as the caller
    // and require the provided amount to be available in this contract to forward to c.
    function check(address caller, address payable recipient, uint256 fund) public payable {
        // fund this test contract if requested
        if (fund > 0) {
            require(address(this).balance >= fund);
            (bool ok,) = address(c).call{value: fund}("");
            // funding call may succeed or fail depending on c's fallback; ignore its result
            ok; // silence unused warning
        }

        // Precondition: the recipient must not be the zero address to avoid ambiguous semantics
        require(recipient != address(0));

        // Capture balances before the call
        uint256 beforeRecipient = recipient.balance;
        uint256 beforeC = address(c).balance;

        // The crucial state-changing call: try to invoke withdrawAll on c from the current caller (msg.sender).
        // Note: the contract under test checks msg.sender against owner in the original, but the mutant checks
        // against address(0). This single call distinguishes them.
        c.withdrawAll(recipient);

        // Observe resulting balances
        uint256 afterRecipient = recipient.balance;
        uint256 afterC = address(c).balance;

        // Property: If the caller is not the owner, the contract should not transfer its balance to the recipient.
        // We express this by asserting that either the recipient's balance did not increase by the full prior c balance,
        // or c's balance did not decrease by its full prior balance, when caller != owner.
        // This will hold for the original (only owner can withdraw everything) and be violated by the mutant
        // which allows non-owner callers (almost anyone) to drain the contract.

        // Fetch owner from c
        address owner = c.owner();

        // If the caller is not the owner, then the full transfer of c's prior balance must NOT have occurred.
        if (msg.sender != owner) {
            // Assert that NOT (recipient gained exactly beforeC and c lost exactly beforeC)
            // Equivalently: (afterRecipient - beforeRecipient) != beforeC OR (beforeC - afterC) != beforeC
            // We write as a single comparison: the net transfer to recipient is not equal to the prior c balance.
            assert((afterRecipient - beforeRecipient) != beforeC);
        } else {
            // If caller is owner, then it's allowed to withdraw; require nothing further.
            assert(true);
        }
    }

    // allow the contract to receive ETH so funding can work
    receive() external payable {}
}

