import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    // fuzzed params: caller (possible attacker) and recipient
    function testFuzz_property(address caller, address recipient) public {
        // keep addresses wide but non-zero for meaningful EOA actors
        vm.assume(caller != address(0));
        vm.assume(recipient != address(0));

        // fund the contract with some ETH from this test harness (owner)
        uint256 funding = 1 ether;
        vm.deal(address(this), funding);
        // send ETH to contract
        c.fallback{value: funding}();
        assert(address(c).balance == funding);

        // Case A: owner (this test contract) calls withdrawAll -> should succeed and drain contract
        // perform call as owner (address(this) is owner because setUp used address(this))
        bool okOwner;
        try c.withdrawAll(address(this)) {
            okOwner = true;
        } catch {
            okOwner = false;
        }
        // after owner withdraw, contract balance should be zero
        bool ownerDrained = address(c).balance == 0;

        // Re-deposit funds for the adversarial call test
        if (!ownerDrained) {
            // if owner call didn't drain (shouldn't happen in reference), re-fund to ensure later check is meaningful
            vm.deal(address(this), funding);
            c.fallback{value: funding}();
        } else {
            // re-fund for non-owner test
            vm.deal(address(this), funding);
            c.fallback{value: funding}();
