        // If the caller is not the owner, then after their call the contract balance must remain equal to funding.
        // We express this as a single assertTrue reading c's public state (address(c).balance).
        if (caller != address(this)) {
            // For the correct contract, non-owner calls cannot withdraw -> balance stays funding
            assertTrue(address(c).balance == funding);
        } else {
            // If caller is the owner, owner is allowed to withdraw; then balance may be 0
            assertTrue(address(c).balance == 0 || address(c).balance == funding);
        }
